package com.adria.account.mcp;import com.adria.account.domain.Account;import com.adria.account.service.AccountService;import org.springframework.stereotype.Component;import org.springframework.ai.mcp.server.annotation.McpTool;import org.springframework.ai.mcp.server.annotation.McpToolParam;import java.util.*;
@Component public class AccountMcpTools {private final AccountService service;public AccountMcpTools(AccountService s){service=s;}@McpTool(description="Consulter un compte bancaire par son identifiant") public Account getAccount(@McpToolParam(description="UUID du compte") String id){return service.get(UUID.fromString(id));}@McpTool(description="Lister les comptes bancaires") public List<Account> getAccounts(){return service.all();}}
